 async function fetchChallenges(){if(!api||!accounts.user)return;const owner=accounts.user.id,token=++request;message='Chargement…';cb.render();try{if(!await ensureCompetition()||!capabilities.challenges)return;const [list,seeds]=await Promise.all([api.challengeList(owner),api.competitionCandidates(owner)]);if(token!==request||accounts.user?.id!==owner)return;challenges=list||[];candidates=seeds||[];challengeOwner=owner;challengeDraft.performance||=candidates[0]?.id||'';message=''}catch{if(challengeOwner!==owner){challenges=[];candidates=[]}message=navigator.onLine?'Défis indisponibles. Réessaie.':'Hors connexion · les défis nécessitent une confirmation du serveur.'}finally{if(token===request&&cb.view()==='ranking')cb.render()}}
